fixed_edges = [(1,8), (1,9), (0,10), (0,6), (0,5)]
additional_edges = [(2,3), (4,7), (11,12), (13,14)]
all_edges = fixed_edges + additional_edges

# Verify degrees
degree = {i: 0 for i in range(15)}
for u, v in all_edges:
    degree[u] += 1
    degree[v] += 1

print("All degrees:", degree)
print("All vertices covered:", all(degree[v] >= 1 for v in range(15)))

# Check for triangles
adj = {i: set() for i in range(15)}
for u, v in all_edges:
    adj[u].add(v)
    adj[v].add(u)

triangle_found = False
for u in range(15):
    for v in adj[u]:
        for w in adj[v]:
            if w != u and w in adj[u]:
                triangle_found = True
                print(f"Triangle: {u},{v},{w}")

print("Triangle-free:", not triangle_found)

# Verify chromatic number (bipartite check)
from collections import deque
color = [-1] * 15
is_bipartite = True
for start in range(15):
    if color[start] == -1:
        color[start] = 0
        q = deque([start])
        while q:
            node = q.popleft()
            for nb in adj[node]:
                if color[nb] == -1:
                    color[nb] = 1 - color[node]
                    q.append(nb)
                elif color[nb] == color[node]:
                    is_bipartite = False

print("Bipartite (chromatic number ≤ 2):", is_bipartite)
print("\nFinal edges:", sorted(all_edges))
